CREATE TRIGGER workflow_snapshot_association AFTER INSERT ON opportunity_contacts WHEN NOT EXISTS(SELECT 1 FROM runtime_controls WHERE name IN('workflow_suppressed','archive_import','restore','archive_applying')) BEGIN
 INSERT OR IGNORE INTO workflow_event_snapshots SELECT e.id,'contact',c.id,json_object('id',c.id,'name',c.name,'email',c.email,'phone',c.phone,'job_title',c.job_title,'timezone',c.timezone,'company_id',c.company_id,'contactability',c.contactability,'custom_fields_json',c.custom_fields_json,'updated_at',c.updated_at) FROM workflow_events e JOIN contacts c ON c.id=NEW.contact_id WHERE e.record_type='opportunity' AND e.record_id=NEW.opportunity_id AND e.id=(SELECT id FROM workflow_events WHERE record_type='opportunity' AND record_id=NEW.opportunity_id AND occurred_at=(SELECT updated_at FROM opportunities WHERE id=NEW.opportunity_id) ORDER BY rowid DESC LIMIT 1);
 UPDATE workflow_event_snapshots SET values_json=json_set(values_json,'$.contact_ids',json((SELECT json_group_array(contact_id) FROM opportunity_contacts WHERE opportunity_id=NEW.opportunity_id)),'$.primary_contact_id',(SELECT contact_id FROM opportunity_contacts WHERE opportunity_id=NEW.opportunity_id AND is_primary=1)) WHERE record_type='opportunity' AND record_id=NEW.opportunity_id AND event_id=(SELECT id FROM workflow_events WHERE record_type='opportunity' AND record_id=NEW.opportunity_id AND occurred_at=(SELECT updated_at FROM opportunities WHERE id=NEW.opportunity_id) ORDER BY rowid DESC LIMIT 1);
END

CREATE TRIGGER sales_task_erase BEFORE DELETE ON sales_tasks
BEGIN
 DELETE FROM timeline_entries WHERE id IN(SELECT entry_id FROM sales_task_timeline WHERE task_id=OLD.id);
 DELETE FROM notifications WHERE id IN(SELECT notification_id FROM sales_task_notification_links WHERE task_id=OLD.id);
 UPDATE audit_entries SET entity_id='erased',details_json='{}' WHERE entity_type='sales_task' AND entity_id=OLD.id;
END

CREATE TRIGGER record_mail_later_native_send AFTER UPDATE OF state ON outbound_messages WHEN NEW.state='accepted' AND OLD.state<>'accepted' BEGIN
 UPDATE record_mail_obligations SET closed_at=NEW.updated_at,closed_reason='Later accepted message' WHERE contact_id=NEW.contact_id AND closed_at IS NULL;
END

CREATE TRIGGER stopped_schedule_queue AFTER UPDATE OF state ON outbound_messages
WHEN NOT EXISTS(SELECT 1 FROM runtime_controls WHERE name='restore')
 AND OLD.state='scheduled' AND NEW.state IN('cancelled','failed','draft')
 AND EXISTS(SELECT 1 FROM opportunities WHERE id=NEW.opportunity_id AND lifecycle='open')
BEGIN
 UPDATE opportunities SET queue_state='now',queue_reason=COALESCE(NEW.failure,'Scheduled outreach stopped'),next_due_at=NULL,updated_at=NEW.updated_at WHERE id=NEW.opportunity_id AND lifecycle='open';
 INSERT OR IGNORE INTO timeline_entries(id,kind,occurred_at,recorded_at,actor_type,actor_id,source,payload_json)
 VALUES('schedule-stop:'||NEW.id||':'||NEW.state,'message.schedule_stopped',NEW.updated_at,NEW.updated_at,'feature',NULL,'outreach',json_object('messageId',NEW.id,'state',NEW.state,'reason',NEW.failure));
 INSERT OR IGNORE INTO timeline_entry_records(timeline_entry_id,record_type,record_id)
 VALUES('schedule-stop:'||NEW.id||':'||NEW.state,'opportunity',NEW.opportunity_id);
 INSERT OR IGNORE INTO audit_entries(id,actor_id,action,entity_type,entity_id,details_json,occurred_at)
 VALUES('schedule-stop:'||NEW.id||':'||NEW.state,NULL,'outreach.schedule_stopped','outbound_message',NEW.id,json_object('feature','outreach','state',NEW.state),NEW.updated_at);
END
